    '2월 초 고교 배정 결과가 나왔다. 종이에는 푸른여고라고 적혀 있다. 한유진, 김혜린, 서은비의 이름이 같은 명단에 있다. 역삼동에서 버스를 타고 다니는 거리다. 한빛고는 남학교라서 여학생은 같은 조건의 푸른여고로 배정된다.',
