const FOUND = '증권사에서 온 우편물을 아버지가 먼저 뜯었다. 저녁 식탁에 잔고 명세서가 놓였다. 어머니는 숫자를 몇 번이나 다시 세었다. 아버지가 한참 만에 입을 열었다. "이걸 네가 혼자 불렸다는 거냐. 어디서 배운 거냐." 놀란 목소리가 곧 낮아졌다. "그래도 넌 아직 학생이다. 공부는 어쩌고, 앞으로는 어쩌려고 그러니."';
